from collections import Counter
def shapes(grid, bg=None):
    vals=Counter(cell for row in grid for cell in row)
    bgval=None
    if bg is None:
        c0=grid[0][0]; bgval=c0
        for v,c in vals.items():
            if c==1 and v!=c0: continue # shape of size 1? skip single noise
            if v!=c0: bgval=v; break
    if bgval is None: bgval=vals.most_common(1)[0][0]
    cols={'a':bgval}
    rest={v: [] for v in vals if v!=bgval}
    h=len(grid); w=len(grid[0])
    for y in range(h):
        for x in range(w):
            v=grid[y][x]
            if v!=bgval and v not in cols:
                cols[v]=[]
            elif v in cols:
                pass
    for v in cols:
        h=len(grid); w=len(grid[0])
        cells=[[y,x] for y in range(h) for x in range(w) if grid[y][x]==v]
        if len(cells)>1 and v!=cols['a']:
            rest[v]=cells
        elif len(cells)==1 and v!=cols['a']:
            rest[v]=cells
    return rest

